-- Remove PL/pgSQL variable/column ambiguity from the canonical recipe commit.
create or replace function tongs.commit_reference_visual_recipe(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,p_recipe_id uuid,p_expected_revision bigint,p_prompt_source text,p_visual_subtype text,p_title text,p_subtitle text,p_recipe_json jsonb,p_evidence_revision_ids uuid[],p_attribution_text text,p_aspect_ratio text,p_accessibility_text text,p_brand_treatment jsonb,p_safe_areas jsonb,p_animation_hints jsonb,p_renderer_contract_version text,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_recipe_sequences%rowtype;prev tongs.reference_visual_recipe_revisions%rowtype;recipe_rev tongs.reference_visual_recipe_revisions%rowtype;n bigint;h text;ih text;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required'using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;
 if exists(select 1 from unnest(p_evidence_revision_ids)e(id)left join tongs.reference_visual_evidence_revisions ev on ev.id=e.id and ev.workspace_id=p_workspace_id and ev.workpiece_id=p_workpiece_id and ev.opportunity_id=p_opportunity_id and ev.confirmation_state='creator_confirmed'where ev.id is null)then return jsonb_build_object('disposition','confirmed_evidence_required');end if;
 select * into seq from tongs.reference_visual_recipe_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id for update;if coalesce(seq.current_recipe_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','recipe_revision_conflict','current_revision',coalesce(seq.current_recipe_revision,0));end if;if p_expected_revision>0 then select * into prev from tongs.reference_visual_recipe_revisions where id=seq.current_recipe_revision_id;end if;n:=p_expected_revision+1;h:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('subtype',p_visual_subtype,'title',p_title,'subtitle',p_subtitle,'recipe',p_recipe_json,'evidence_revision_ids',p_evidence_revision_ids,'attribution',p_attribution_text,'aspect_ratio',p_aspect_ratio,'accessibility',p_accessibility_text,'brand',p_brand_treatment,'safe_areas',p_safe_areas,'animation',p_animation_hints,'renderer_contract_version',p_renderer_contract_version))::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',n,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_recipe_revisions(recipe_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,prompt_source,visual_subtype,title,subtitle,recipe_json,evidence_revision_ids,attribution_text,aspect_ratio,accessibility_text,brand_treatment_json,safe_areas_json,animation_hints_json,renderer_contract_version,content_hash,immutable_revision_hash,created_by)values(p_recipe_id,p_workspace_id,p_workpiece_id,p_opportunity_id,n,prev.id,prev.revision,p_prompt_source,p_visual_subtype,p_title,p_subtitle,p_recipe_json,p_evidence_revision_ids,p_attribution_text,p_aspect_ratio,p_accessibility_text,coalesce(p_brand_treatment,'{}'),coalesce(p_safe_areas,'{}'),coalesce(p_animation_hints,'{}'),p_renderer_contract_version,h,ih,p_actor_id)returning * into recipe_rev;
 insert into tongs.reference_visual_recipe_sequences values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_recipe_id,recipe_rev.id,recipe_rev.revision,now())on conflict(workspace_id,workpiece_id,opportunity_id)do update set recipe_id=excluded.recipe_id,current_recipe_revision_id=excluded.current_recipe_revision_id,current_recipe_revision=excluded.current_recipe_revision,updated_at=now();result:=jsonb_build_object('disposition','committed','recipe_revision',to_jsonb(recipe_rev));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'recipe_commit',p_workspace_id,p_workpiece_id,'committed',recipe_rev.id,result,p_actor_id,now());return result;
end$$;
revoke all on function tongs.commit_reference_visual_recipe(uuid,uuid,uuid,uuid,bigint,text,text,text,text,jsonb,uuid[],text,text,text,jsonb,jsonb,jsonb,text,text,text,uuid)from public,anon,authenticated;grant execute on function tongs.commit_reference_visual_recipe(uuid,uuid,uuid,uuid,bigint,text,text,text,text,jsonb,uuid[],text,text,text,jsonb,jsonb,jsonb,text,text,text,uuid)to authenticated,service_role;
